-- The level-17 backfill, applied to a scratch database and checked.
--
-- Generated by scripts/build-level17-migration.mjs --fixture. Regenerate
-- rather than editing, or it stops describing the migration it tests.
--
-- Eight categories advertised fewer than 17 levels. In six of them that
-- was never a content shortage: Georgian held roughly twice what every
-- other language did, because translate-questions only ever fans the
-- ENGLISH bank out and a question authored in Georgian is invisible to
-- it. The migration translates that tail. This seeds a database with
-- the same shape and proves the tail lands where it is needed.

\set ON_ERROR_STOP on
\pset pager off

CREATE OR REPLACE FUNCTION pg_temp.must_equal(got bigint, want bigint, label text)
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  IF got IS DISTINCT FROM want THEN
    RAISE EXCEPTION 'FAILED: % -- got %, want %', label, got, want;
  END IF;
END $$;

-- A clean slate for exactly the eight slugs this touches; anything else
-- in the database belongs to another test file.
DELETE FROM questions WHERE category_id IN (SELECT id FROM categories WHERE category_id IN ('anime_manga', 'ecology', 'fun_facts', 'myths_reality', 'psychology', 'science', 'spanish_literature', 'portuguese_literature'));
DELETE FROM categories WHERE category_id IN ('anime_manga', 'ecology', 'fun_facts', 'myths_reality', 'psychology', 'science', 'spanish_literature', 'portuguese_literature');

