-- Before: every one of them is short.
DO $$
DECLARE n bigint;
BEGIN
  SELECT count(*) INTO n FROM public.categories c
   WHERE c.category_id IN ('anime_manga', 'ecology', 'fun_facts', 'myths_reality', 'psychology', 'science', 'spanish_literature', 'portuguese_literature')
     AND (SELECT count(*) FROM public.questions q
           WHERE q.category_id = c.id AND q.language = 'en' AND q.is_active AND q.in_production) >= 170;
  PERFORM pg_temp.must_equal(n, 0, 'no shared category starts at 170 English questions');
END $$;

\i supabase/migrations/20260914100000_level17_backfill.sql

-- And again, because "re-runnable" is the claim most likely to be false
-- and least likely to be noticed.
\i supabase/migrations/20260914100000_level17_backfill.sql

-- After: 170 in every language served, counted exactly — a second
-- run that duplicated its rows would read 340 here, not 170.
DO $$
DECLARE n bigint;
BEGIN
  SELECT count(*) INTO n FROM public.questions q JOIN public.categories c ON c.id = q.category_id
   WHERE c.category_id = 'anime_manga' AND q.language = 'ka' AND q.is_active AND q.in_production;
  PERFORM pg_temp.must_equal(n, 184, 'anime_manga/ka');
  SELECT count(*) INTO n FROM public.questions q JOIN public.categories c ON c.id = q.category_id
   WHERE c.category_id = 'anime_manga' AND q.language = 'en' AND q.is_active AND q.in_production;
  PERFORM pg_temp.must_equal(n, 170, 'anime_manga/en');
  SELECT count(*) INTO n FROM public.questions q JOIN public.categories c ON c.id = q.category_id
   WHERE c.category_id = 'anime_manga' AND q.language = 'de' AND q.is_active AND q.in_production;
  PERFORM pg_temp.must_equal(n, 170, 'anime_manga/de');
  SELECT count(*) INTO n FROM public.questions q JOIN public.categories c ON c.id = q.category_id
   WHERE c.category_id = 'anime_manga' AND q.language = 'es' AND q.is_active AND q.in_production;
  PERFORM pg_temp.must_equal(n, 170, 'anime_manga/es');
  SELECT count(*) INTO n FROM public.questions q JOIN public.categories c ON c.id = q.category_id
   WHERE c.category_id = 'anime_manga' AND q.language = 'fr' AND q.is_active AND q.in_production;
