-- The number the player is shown, which the trigger owns.
DO $$
DECLARE r record;
BEGIN
  FOR r IN SELECT category_id, total_levels FROM public.categories
            WHERE category_id IN ('anime_manga', 'ecology', 'fun_facts', 'myths_reality', 'psychology', 'science', 'spanish_literature', 'portuguese_literature') LOOP
    PERFORM pg_temp.must_equal(r.total_levels, 17, r.category_id || ' total_levels');
  END LOOP;
END $$;

-- Lineage: each translated row points at the Georgian question it came
-- from. Pointing the ENGLISH row at the Georgian source, rather than the
-- other way round, is what keeps get_untranslated_questions from later
-- picking these up and translating them back into Georgian as
-- duplicates — it only ever selects English rows whose translated_from
-- is NULL.
DO $$
DECLARE n bigint;
BEGIN
  SELECT count(*) INTO n FROM public.questions t
    JOIN public.questions src ON src.id = t.translated_from
   WHERE src.language = 'ka' AND t.language <> 'ka'
     AND src.category_id IN (SELECT id FROM public.categories WHERE category_id IN ('anime_manga', 'ecology', 'fun_facts', 'myths_reality', 'psychology', 'science'));
  PERFORM pg_temp.must_equal(n, 402, 'translated rows linked to a Georgian source');

  SELECT count(*) INTO n FROM public.questions
   WHERE language = 'en' AND translated_from IS NOT NULL AND is_active AND in_production
     AND category_id IN (SELECT id FROM public.categories WHERE category_id IN ('anime_manga', 'ecology', 'fun_facts', 'myths_reality', 'psychology', 'science'));
  PERFORM pg_temp.must_equal(n, 67, 'English rows the translator will now skip');
END $$;

-- The icon and the difficulty come from the source rather than being
-- invented, so a translated row looks like the question it translates.
DO $$
DECLARE n bigint;
BEGIN
  SELECT count(*) INTO n FROM public.questions t
    JOIN public.questions src ON src.id = t.translated_from
   WHERE src.language = 'ka'
     AND (t.icon_slug IS DISTINCT FROM src.icon_slug
       OR t.difficulty IS DISTINCT FROM src.difficulty
       OR t.level_number IS DISTINCT FROM src.level_number
       OR t.category_id IS DISTINCT FROM src.category_id);
  PERFORM pg_temp.must_equal(n, 0, 'translated rows inherit icon, difficulty, level and category');
END $$;

